public class JsonMappingExceptionTest{
@Rule
    public ExpectedException expectedException = ExpectedException.none();

    @Before
    public void init(){

    }

    @Test
    public void testWrapWithPath(){
        Throwable throwable = new Exception();
        Object refFrom = new Object();
        String refFieldName = "field";

        JsonMappingException exception = JsonMappingException.wrapWithPath(throwable, refFrom, refFieldName);

        assertNotNull(exception);
        assertEquals(throwable, exception.getCause());

        List<Reference> path = exception.getPath();
        assertNotNull(path);
        assertEquals(1, path.size());

