        Object result = deserializer.getEmptyValue(ctxt);
        assertThat(result, instanceOf(AtomicReference.class));
        assertThat(((AtomicReference<?>) result).get(), nullValue());
    }

    @Test
    public void testGetNullValue() throws Exception {
        DeserializationContext ctxt = mock(DeserializationContext.class);
        AtomicReference<Object> result = deserializer.getNullValue(ctxt);
        assertThat(result, notNullValue());
        assertThat(result.get(), nullValue());
    }

