    public void testSetAll_NullValue(){
        Map<String, JsonNode> properties = new LinkedHashMap<>();
        properties.put("key1", jsonNodeFactory.textNode("value1"));
        properties.put("key2", null);

        objectNode.setAll(properties);

        assertThat(objectNode.get("key1").asText(), equalTo("value1"));
        assertThat(objectNode.get("key2").isNull(), equalTo(true));
    }

    @Test
    public void testSetAll_EmptyMap(){
        Map<String, JsonNode> properties = new LinkedHashMap<>();

        objectNode.setAll(properties);

        assertThat(objectNode.size(), equalTo(0));
    }

    @Test
    public void testSetAll_LargeMap(){
        Map<String, JsonNode> properties = new LinkedHashMap<>();
        for (int i = 0; i < 100; i++) {
            properties.put("key" + i, jsonNodeFactory.textNode("value" + i));
        }

        objectNode.setAll(properties);

        assertThat(objectNode.size(), equalTo(100));
    }
