public class BaseSettingsTest{
private BaseSettings baseSettings;
    @Before
    public void setUp() {
        ClassIntrospector ci = new ClassIntrospector();
        AnnotationIntrospector ai = new AnnotationIntrospector();
        VisibilityChecker<?> vc = VisibilityChecker.NOISY;
        PropertyNamingStrategy pns = PropertyNamingStrategy.SNAKE_CASE;
        TypeFactory tf = TypeFactory.defaultInstance();
        TypeResolverBuilder<?> typer = new TypeResolverBuilder();
        DateFormat dateFormat = new StdDateFormat();
        HandlerInstantiator hi = new HandlerInstantiator();
        Locale locale = Locale.US;
        TimeZone tz = TimeZone.getDefault();
        Base64Variant defaultBase64 = Base64Variants.RFC_4648;
        baseSettings = new BaseSettings(ci, ai, vc, pns, tf, typer, dateFormat, hi, locale, tz, defaultBase64);
    }

    @Test
    public void testWithHandlerInstantiatorDiff() {
        HandlerInstantiator hi = mock(HandlerInstantiator.class);
        BaseSettings newSettings = baseSettings.withHandlerInstantiator(hi);
        Assert.assertNotEquals(baseSettings, newSettings);
        Assert.assertEquals(hi, newSettings.getHandlerInstantiator());
    }

    @Test
    public void testWithHandlerInstantiatorSame() {
        BaseSettings newSettings = baseSettings.withHandlerInstantiator(baseSettings.getHandlerInstantiator());
        Assert.assertEquals(baseSettings, newSettings);
    }

    @Test
    public void testGetter() {
