        Assert.assertNotNull(baseSettings.getHandlerInstantiator());
        Assert.assertNotNull(baseSettings.getLocale());
        Assert.assertNotNull(baseSettings.getTimeZone());
        Assert.assertNotNull(baseSettings.getBase64Variant());
    }

}
