    public void testAcceptJsonFormatVisitor_Int() throws JsonMappingException{
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);
        numberSerializerInt.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).visitIntFormat(any(JsonFormatVisitorWrapper.class), eq(typeHint), eq(JsonParser.NumberType.BIG_INTEGER));
    }

    @Test
    public void testAcceptJsonFormatVisitor_BigDecimal() throws JsonMappingException{
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);
        numberSerializerBigDecimal.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).visitFloatFormat(any(JsonFormatVisitorWrapper.class), eq(typeHint), eq(JsonParser.NumberType.BIG_DECIMAL));
    }

