    public void testAcceptJsonFormatVisitor_ExpectNumberFormat() throws JsonMappingException{
        NumberSerializer numberSerializer = new NumberSerializer(Double.class);
        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);
        numberSerializer.acceptJsonFormatVisitor(visitor, typeHint);
        verify(visitor).expectNumberFormat(eq(typeHint));
    }

