import java.io.IOException;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;

public class NullifyingDeserializerTest{
private NullifyingDeserializer target;
    private JsonParser parser;
    private DeserializationContext ctxt;

    @Before
    public void init(){
        target = NullifyingDeserializer.instance;
        ctxt = mock(DeserializationContext.class);
        parser = mock(JsonParser.class);
    }

    @Test
    public void testDeserialize_FieldName() throws IOException{
        when(parser.hasToken(JsonToken.FIELD_NAME)).thenReturn(true);
        when(parser.nextToken()).thenReturn(JsonToken.START_ARRAY).thenReturn(JsonToken.END_ARRAY).thenReturn(JsonToken.END_OBJECT);
        Object result = target.deserialize(parser, ctxt);
        Assert.assertNull(result);
        verify(parser).nextToken();
        verify(parser).skipChildren();
    }

    @Test
    public void testDeserialize_NotFieldName() throws IOException{
        when(parser.hasToken(JsonToken.FIELD_NAME)).thenReturn(false);
        Object result = target.deserialize(parser, ctxt);
        Assert.assertNull(result);
        verify(parser).skipChildren();
    }

    @Test
    public void testDeserialize_Null() throws IOException{
        when(parser.hasToken(JsonToken.FIELD_NAME)).thenReturn(true);
        when(parser.nextToken()).thenReturn(null);
        Object result = target.deserialize(parser, ctxt);
        Assert.assertNull(result);
        verify(parser).nextToken();
    }

    @Test
    public void testDeserialize_EndObject() throws IOException{
        when(parser.hasToken(JsonToken.FIELD_NAME)).thenReturn(true);
        when(parser.nextToken()).thenReturn(JsonToken.END_OBJECT);
        Object result = target.deserialize(parser, ctxt);
        Assert.assertNull(result);
        verify(parser).nextToken();
    }
}
