        assertEquals(JsonProperty.Access.AUTO, access);
    }

    @Test
    public void testRemoveNonVisible_InferMutators_True() {
        JsonProperty.Access access = builder.removeNonVisible(true);
        assertEquals(JsonProperty.Access.AUTO, access);
    }

    @Test
    public void testAnyVisible() {
        assertFalse(builder.anyVisible());
    }

    @Test
    public void testAnyIgnorals() {
        assertFalse(builder.anyIgnorals());
    }

