public class ResolvedRecursiveTypeTest{
private ResolvedRecursiveType instance;

    @Before
    public void setup() throws Exception {
        instance = new ResolvedRecursiveType(String.class, null);
    }

    @Test
    public void testGetSelfReferencedType() throws Exception {
        instance.setReference(null);
        Assert.assertNull(instance.getSelfReferencedType());

        JavaType mockType = mock(JavaType.class);
        instance.setReference(mockType);
        Assert.assertEquals(mockType, instance.getSelfReferencedType());
    }

    @Test
    public void testSetReference() throws Exception {
        JavaType mockType = mock(JavaType.class);
        instance.setReference(mockType);
        Assert.assertEquals(mockType, instance.getSelfReferencedType());
    }

    @Test
    public void testGetSuperClass() throws Exception {
        // test super class
        JavaType superClass = instance.getSuperClass();
        Assert.assertNull(superClass);

        // mocking field  _referencedType
        JavaType mockType = mock(JavaType.class);
        instance.setReference(mockType);

        // mock super class
        JavaType mockSuperClass = mock(JavaType.class);
        when(mockType.getSuperClass()).thenReturn(mockSuperClass);
        superClass = instance.getSuperClass();
        Assert.assertEquals(mockSuperClass, superClass);
    }

    @Test
