import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;

public class TypeFactoryTest{
private TypeFactory typeFactory;

	@Before
	public void before(){
		typeFactory = TypeFactory.defaultInstance();
	}

	@After
	public void after(){
		typeFactory.clearCache();
	}

	@Test
	public void testConstructParametricType_validInput(){
		Class<?> parametrized = List.class;
		Class<?>[] parameterClasses = {String.class};
		JavaType javaType = typeFactory.constructParametricType(parametrized, parameterClasses);
		assertNotNull(javaType);
		assertEquals(parametrized, javaType.getRawClass());
	}

	@Test(expected = NullPointerException.class)
	public void testConstructParametricType_nullParametrized(){
		Class<?> parametrized = null;
		Class<?>[] parameterClasses = {String.class};
		typeFactory.constructParametricType(parametrized, parameterClasses);
	}

	@Test(expected = NullPointerException.class)
	public void testConstructParametricType_nullParameterClasses(){
		Class<?> parametrized = List.class;
		Class<?>[] parameterClasses = null;
		typeFactory.constructParametricType(parametrized, parameterClasses);
	}

	@Test(expected = IllegalArgumentException.class)
	public void testConstructParametricType_emptyParameterClasses(){
		Class<?> parametrized = List.class;
		Class<?>[] parameterClasses = {};
		typeFactory.constructParametricType(parametrized, parameterClasses);
	}

	@Test
	public void testConstructParametricType_multipleParameterClasses(){
		Class<?> parametrized = Map.class;
		Class<?>[] parameterClasses = {String.class, Integer.class};
		JavaType javaType = typeFactory.constructParametricType(parametrized, parameterClasses);
		assertNotNull(javaType);
		assertEquals(parametrized, javaType.getRawClass());
	}
}
