public class POJONodeTest{
private POJONode pojoNode;
    private JsonGenerator gen;
    private SerializerProvider ctxt;

    @Before
    public void before() throws Exception{
        gen = mock(JsonGenerator.class);
        ctxt = mock(SerializerProvider.class);
    }

    @Test 
    public void testSerialize_null()throws Exception{
        pojoNode = new POJONode(null);
        pojoNode.serialize(gen, ctxt);
        verify(ctxt).defaultSerializeNull(gen);
    }

    @Test 
    public void testSerialize_jsonSerializable()throws Exception{
        JsonSerializable jsonSerializable = mock(JsonSerializable.class);
        pojoNode = new POJONode(jsonSerializable);
        pojoNode.serialize(gen, ctxt);
        verify(jsonSerializable).serialize(gen, ctxt);
    }

    @Test 
    public void testSerialize_notJsonSerializable()throws Exception{
        Object obj = "test";
        pojoNode = new POJONode(obj);
        pojoNode.serialize(gen, ctxt);
        verify(ctxt).defaultSerializeValue(obj, gen);
    }

    @Test 
    public void testGetPojo()throws Exception{
        Object obj = "test";
        pojoNode = new POJONode(obj);
        Assert.assertEquals(obj,pojoNode.getPojo());
    }
}
